package dev.dwmir.lib;
import com.google.gson.*;import java.nio.file.*;import java.time.Instant;import java.util.*;import net.fabricmc.loader.api.FabricLoader;
/** A profile contains only settings explicitly exported by registered modules. */
public final class ProfileStore {
 public record Mod(String id,String name,String version,List<String> files){}public record Profile(String id,String name,String created,String theme,boolean tooltips,List<Mod> mods){}
 private static final Gson JSON=new GsonBuilder().setPrettyPrinting().create();public static Path root(){return FabricLoader.getInstance().getConfigDir().resolve("dwmirlib/profiles");}private static Path config(){return FabricLoader.getInstance().getConfigDir();}
 private static Path directory(String id){String valid=UUID.fromString(id).toString();return root().resolve(valid);}private static Path safe(Path base,String rel){Path p=base.resolve(rel).normalize();if(!p.startsWith(base.normalize())||Path.of(rel).isAbsolute())throw new IllegalArgumentException("Invalid profile file");return p;}
 public static List<Profile> list(){var out=new ArrayList<Profile>();if(!Files.isDirectory(root()))return out;try(var dirs=Files.list(root())){dirs.filter(Files::isDirectory).forEach(p->{try{var v=JSON.fromJson(Files.readString(p.resolve("profile.json")),Profile.class);if(v!=null&&p.equals(directory(v.id))&&v.mods!=null)out.add(v);}catch(Exception e){org.slf4j.LoggerFactory.getLogger("dwmirlib").warn("Ignoring invalid profile {}",p.getFileName());}});}catch(Exception e){throw new IllegalStateException("Profiles could not be read",e);}out.sort(Comparator.comparing(Profile::created).reversed());return out;}
 public static Profile capture(String name)throws Exception{String clean=name==null?"":name.strip();if(clean.isBlank()||clean.length()>64)throw new IllegalArgumentException("Use a name with 1 to 64 characters");var mods=new ArrayList<Mod>();String id=UUID.randomUUID().toString();Path dir=directory(id);Files.createDirectories(dir);for(var e:DwmirLib.MODULES.entrySet()){var module=e.getValue();module.flushProfile();var files=new ArrayList<String>();for(String file:module.profileFiles()){Path source=safe(config(),file);if(!Files.isRegularFile(source))continue;if(Files.size(source)>16*1024*1024)throw new IllegalArgumentException("Profile asset exceeds 16 MB");Path target=safe(dir.resolve(e.getKey()),file);Files.createDirectories(target.getParent());Files.copy(source,target,StandardCopyOption.REPLACE_EXISTING);files.add(file);}var meta=FabricLoader.getInstance().getModContainer(e.getKey()).orElseThrow().getMetadata();if(!files.isEmpty())mods.add(new Mod(e.getKey(),meta.getName(),meta.getVersion().getFriendlyString(),files));}Profile p=new Profile(id,clean,Instant.now().toString(),LibraryState.theme.name(),LibraryState.tooltips,mods);write(dir.resolve("profile.json"),JSON.toJson(p).getBytes(java.nio.charset.StandardCharsets.UTF_8));return p;}
 public static int apply(Profile profile)throws Exception{Path dir=directory(profile.id);var updates=new LinkedHashMap<Path,byte[]>();var backup=new LinkedHashMap<Path,byte[]>();var reload=new ArrayList<dev.dwmir.lib.api.DwmirModule>();for(var m:profile.mods){var module=DwmirLib.MODULES.get(m.id);if(module==null)continue;for(String file:m.files){if(!module.profileFiles().contains(file))throw new IllegalArgumentException("Unrecognized settings file");Path source=safe(dir.resolve(m.id),file);if(Files.size(source)>16*1024*1024)throw new IllegalArgumentException("Profile asset exceeds 16 MB");byte[] bytes=Files.readAllBytes(source);if(file.endsWith(".json"))JsonParser.parseString(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));Path target=safe(config(),file);updates.put(target,bytes);backup.put(target,Files.exists(target)?Files.readAllBytes(target):null);}reload.add(module);}try{for(var e:updates.entrySet())write(e.getKey(),e.getValue());for(var m:reload)m.reloadProfile();LibraryState.select(LibraryState.Theme.valueOf(profile.theme));if(LibraryState.tooltips!=profile.tooltips)LibraryState.toggleTooltips();return reload.size();}catch(Exception failure){for(var e:backup.entrySet()){if(e.getValue()==null)Files.deleteIfExists(e.getKey());else write(e.getKey(),e.getValue());}for(var m:reload)m.reloadProfile();throw failure;}}
 private static void write(Path file,byte[] bytes)throws Exception{Files.createDirectories(file.getParent());Path temp=file.resolveSibling(file.getFileName()+".profile-tmp");Files.write(temp,bytes);try{Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}}
}
